      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DN0107' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) AS numerator,
            COUNT(*) FILTER (WHERE NOT died) AS denominator,
            ROUND((
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) * 100.0) / NULLIF(COUNT(*) FILTER (WHERE NOT died), 0), 2) AS value
          FROM periodized
          WHERE LEFT(pdx, 3) IN ('I60', 'I61', 'I62', 'I63', 'I64', 'I65', 'I66', 'I67')
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0107', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DN0107' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0053\0074\0072\006F\006B\0065\0020\0E14\0E49\0E27\0E22\0E42\0E23\0E04\0E2B\0E25\0E2D\0E14\0E40\0E25\0E37\0E2D\0E14\0E2A\0E21\0E2D\0E07\0E40\0E14\0E34\0E21\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19' AS indicator_name_th,
            'Stroke: Percent of unplanned re-admission of stroke within 28 days' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DN0107
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0109', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DN0109' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            ROUND(SUM(los)::numeric, 2) AS numerator,
            COUNT(*) AS denominator,
            ROUND(AVG(los), 2) AS value
          FROM periodized
          WHERE LEFT(pdx, 3) IN ('I60', 'I61', 'I62', 'I63', 'I64', 'I65', 'I66', 'I67')
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0109', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 1.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DN0109' AS indicator_code,
            U&'\0E23\0E30\0E22\0E30\0E40\0E27\0E25\0E32\0E27\0E31\0E19\0E19\0E2D\0E19\0E40\0E09\0E25\0E35\0E48\0E22\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0053\0074\0072\006F\006B\0065' AS indicator_name_th,
            'Stroke: Average length of stay' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DN0109
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0110', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DN0110' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM ovst v
              JOIN er_regist er ON er.vn = v.vn
              WHERE v.an = periodized.an
                AND er.do_stroke_needle = 'Y'
                AND er.enter_er_time IS NOT NULL
                AND er.stroke_needle_datetime IS NOT NULL
                AND er.stroke_needle_datetime >= er.enter_er_time
                AND EXTRACT(EPOCH FROM (er.stroke_needle_datetime - er.enter_er_time)) <= 3600) OR EXISTS (
              SELECT 1
              FROM opitemrece oi
              JOIN drugitems di ON di.icode = oi.icode
              WHERE oi.an = periodized.an
                AND (di.name ILIKE '%streptokinase%' OR di.name ILIKE '%alteplase%' OR di.name ILIKE '%tenecteplase%' OR di.name ILIKE '%reteplase%' OR di.name ILIKE '%urokinase%')
                AND EXISTS (
                  SELECT 1
                  FROM ovst v
                  JOIN er_regist er ON er.vn = v.vn
                  WHERE v.an = periodized.an
                    AND er.enter_er_time IS NOT NULL
                    AND (oi.rxdate::timestamp + COALESCE(oi.rxtime, TIME '00:00:00')) >= er.enter_er_time
                    AND (oi.rxdate::timestamp + COALESCE(oi.rxtime, TIME '00:00:00')) <= er.enter_er_time + INTERVAL '60 minutes'
                ))) AS numerator,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM ovst v
              JOIN er_regist er ON er.vn = v.vn
              WHERE v.an = periodized.an
                AND er.do_stroke_needle = 'Y') OR EXISTS (
              SELECT 1
              FROM opitemrece oi
              JOIN drugitems di ON di.icode = oi.icode
              WHERE oi.an = periodized.an
                AND (di.name ILIKE '%streptokinase%' OR di.name ILIKE '%alteplase%' OR di.name ILIKE '%tenecteplase%' OR di.name ILIKE '%reteplase%' OR di.name ILIKE '%urokinase%'))) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM ovst v
              JOIN er_regist er ON er.vn = v.vn
              WHERE v.an = periodized.an
                AND er.do_stroke_needle = 'Y'
                AND er.enter_er_time IS NOT NULL
                AND er.stroke_needle_datetime IS NOT NULL
                AND er.stroke_needle_datetime >= er.enter_er_time
                AND EXTRACT(EPOCH FROM (er.stroke_needle_datetime - er.enter_er_time)) <= 3600) OR EXISTS (
              SELECT 1
              FROM opitemrece oi
              JOIN drugitems di ON di.icode = oi.icode
              WHERE oi.an = periodized.an
                AND (di.name ILIKE '%streptokinase%' OR di.name ILIKE '%alteplase%' OR di.name ILIKE '%tenecteplase%' OR di.name ILIKE '%reteplase%' OR di.name ILIKE '%urokinase%')
                AND EXISTS (
                  SELECT 1
                  FROM ovst v
                  JOIN er_regist er ON er.vn = v.vn
                  WHERE v.an = periodized.an
                    AND er.enter_er_time IS NOT NULL
                    AND (oi.rxdate::timestamp + COALESCE(oi.rxtime, TIME '00:00:00')) >= er.enter_er_time
                    AND (oi.rxdate::timestamp + COALESCE(oi.rxtime, TIME '00:00:00')) <= er.enter_er_time + INTERVAL '60 minutes'
                )))) * 100 / NULLIF((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM ovst v
              JOIN er_regist er ON er.vn = v.vn
              WHERE v.an = periodized.an
                AND er.do_stroke_needle = 'Y') OR EXISTS (
              SELECT 1
              FROM opitemrece oi
              JOIN drugitems di ON di.icode = oi.icode
              WHERE oi.an = periodized.an
                AND (di.name ILIKE '%streptokinase%' OR di.name ILIKE '%alteplase%' OR di.name ILIKE '%tenecteplase%' OR di.name ILIKE '%reteplase%' OR di.name ILIKE '%urokinase%')))), 0), 2) AS value
          FROM periodized
          WHERE age_y >= 18 AND LEFT(pdx, 3) = 'I63'
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0110', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DN0110' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0020\0049\0073\0063\0068\0065\006D\0069\0063\0020\0073\0074\0072\006F\006B\0065\0020\0E17\0E35\0E48\0E44\0E14\0E49\0E23\0E31\0E1A\0020\0054\0068\0072\006F\006D\0062\006F\006C\0079\0074\0069\0063\0020\0061\0067\0065\006E\0074\0073\0020\0E20\0E32\0E22\0E43\0E19\0020\0036\0030\0020\0E19\0E32\0E17\0E35\0020\0E40\0E21\0E37\0E48\0E2D\0020\0E21\0E32\0E16\0E36\0E07\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25' AS indicator_name_th,
            'Ischemic Stroke: Percent of time to thrombolytic administration agents within 60 minutes of arrival' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DN0110
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0301', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DN0301' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) AS numerator,
            COUNT(*) FILTER (WHERE NOT died) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            ))) * 100 / NULLIF((COUNT(*) FILTER (WHERE NOT died)), 0), 2) AS value
          FROM periodized
          WHERE age_y >= 18 AND LEFT(pdx, 3) IN ('S02', 'S06') AND EXISTS (
              SELECT 1
              FROM iptoprt o
              WHERE o.an = periodized.an
                AND LEFT(REPLACE(UPPER(TRIM(o.icd9)), '.', ''), 3) IN ('012', '013', '014', '015', '016')
            )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0301', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DN0301' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E17\0E35\0E48\0E17\0E33\0020\0043\0072\0061\006E\0069\006F\0074\006F\006D\0079\0020\0E42\0E14\0E22\0E21\0E35\0E2A\0E32\0E40\0E2B\0E15\0E38\0E08\0E32\0E01\0E01\0E32\0E23\0020\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0020\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19' AS indicator_name_th,
            'Head Injury: Percent of unplanned re-admission of Craniotomy within 28 days' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DN0301
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0302', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DN0302' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE died_within_48h) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE died_within_48h) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE pdx IN ('S060', 'S061', 'S062', 'S063', 'S064', 'S065', 'S066', 'S067', 'S068', 'S069')
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0302', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DN0302' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0E17\0E35\0E48\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E20\0E32\0E22\0E43\0E19\0020\0034\0038\0020\0E0A\0E31\0E48\0E27\0E42\0E21\0E07\0020\0E20\0E32\0E22\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0020\0028\0E40\0E09\0E1E\0E32\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E15\0E48\0E2D\0E2A\0E21\0E2D\0E07\0029' AS indicator_name_th,
            'Head Injury: Percent of mortality within 48 hours' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DN0302
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0303', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DN0303' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptoprt o
              WHERE o.an = periodized.an
                AND LEFT(REPLACE(UPPER(TRIM(o.icd9)), '.', ''), 3) IN ('012', '013', '014', '015', '016')
            )) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptoprt o
              WHERE o.an = periodized.an
                AND LEFT(REPLACE(UPPER(TRIM(o.icd9)), '.', ''), 3) IN ('012', '013', '014', '015', '016')
            ))) * 100 / NULLIF((COUNT(*)), 0), 2) AS value
          FROM periodized
          WHERE age_y >= 18 AND LEFT(pdx, 3) = 'S06'
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DN0303', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DN0303' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E1C\0E48\0E32\0E15\0E31\0E14\0E2A\0E21\0E2D\0E07\0E43\0E19\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1A\0E32\0E14\0E40\0E08\0E47\0E1A\0E17\0E35\0E48\0E28\0E35\0E23\0E29\0E30\0E17\0E35\0E48\0E21\0E35\0020\0049\006E\0074\0072\0061\0063\0072\0061\006E\0069\0061\006C\0020\0069\006E\006A\0075\0072\0079' AS indicator_name_th,
            'Head Injury: Percent of patient underwent craniotomy for Intracranial injury' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DN0303
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0202', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DO0202' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptoprt o
              JOIN opitemrece oi ON oi.an = o.an
              JOIN drugitems di ON di.icode = oi.icode
              WHERE o.an = periodized.an
                AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8151', '8152', '8153')
                AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
                AND EXTRACT(EPOCH FROM (
                  (o.opdate + COALESCE(o.optime, TIME '00:00:00')) -
                  (oi.vstdate + COALESCE(oi.vsttime, TIME '00:00:00'))
                )) BETWEEN 0 AND 3600)) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptoprt o
              JOIN opitemrece oi ON oi.an = o.an
              JOIN drugitems di ON di.icode = oi.icode
              WHERE o.an = periodized.an
                AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8151', '8152', '8153')
                AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
                AND EXTRACT(EPOCH FROM (
                  (o.opdate + COALESCE(o.optime, TIME '00:00:00')) -
                  (oi.vstdate + COALESCE(oi.vsttime, TIME '00:00:00'))
                )) BETWEEN 0 AND 3600)) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE EXISTS (
          SELECT 1 FROM iptoprt o
          WHERE o.an = periodized.an
            AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8151', '8152', '8153')
        )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0202', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DO0202' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1C\0E48\0E32\0E15\0E31\0E14\0E40\0E1B\0E25\0E35\0E48\0E22\0E19\0E02\0E49\0E2D\0E2A\0E30\0E42\0E1E\0E01\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0020\0070\0072\006F\0070\0068\0079\006C\0061\0063\0074\0069\0063\0020\0061\006E\0074\0069\0062\0069\006F\0074\0069\0063' AS indicator_name_th,
            'Hip arthroplasty: Percent of patients who received antibiotic prophylaxis in Hip arthroplasty' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DO0202
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0204', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DO0204' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'T845'
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '365 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') = 'T845'
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') = 'T845'
                ))) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'T845'
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '365 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') = 'T845'
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') = 'T845'
                ))) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE EXISTS (
          SELECT 1 FROM iptoprt o
          WHERE o.an = periodized.an
            AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8151', '8152', '8153')
        )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0204', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DO0204' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E41\0E1C\0E25\0E1C\0E48\0E32\0E15\0E31\0E14\0E40\0E1B\0E25\0E35\0E48\0E22\0E19\0E02\0E49\0E2D\0E2A\0E30\0E42\0E1E\0E01\0E20\0E32\0E22\0E43\0E19\0020\0031\0020\0E1B\0E35' AS indicator_name_th,
            'Hip arthroplasty: Percent of Hip arthroplasty associated infection within 1 Year' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DO0204
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0205', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DO0205' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('T845', 'T814')
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '90 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') IN ('T845', 'T814')
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') IN ('T845', 'T814')
                ))) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('T845', 'T814')
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '90 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') IN ('T845', 'T814')
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') IN ('T845', 'T814')
                ))) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE EXISTS (
          SELECT 1 FROM iptoprt o
          WHERE o.an = periodized.an
            AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8151', '8152', '8153')
        )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0205', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DO0205' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E41\0E1C\0E25\0E1C\0E48\0E32\0E15\0E31\0E14\0E40\0E1B\0E25\0E35\0E48\0E22\0E19\0E02\0E49\0E2D\0E2A\0E30\0E42\0E1E\0E01\0E20\0E32\0E22\0E43\0E19\0020\0039\0030\0020\0E27\0E31\0E19' AS indicator_name_th,
            'Hip arthroplasty: Percent of Hip arthroplasty associated infection within 90 days' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DO0205
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0302', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DO0302' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptoprt o
              JOIN opitemrece oi ON oi.an = o.an
              JOIN drugitems di ON di.icode = oi.icode
              WHERE o.an = periodized.an
                AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8154', '8155')
                AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
                AND EXTRACT(EPOCH FROM (
                  (o.opdate + COALESCE(o.optime, TIME '00:00:00')) -
                  (oi.vstdate + COALESCE(oi.vsttime, TIME '00:00:00'))
                )) BETWEEN 0 AND 3600)) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptoprt o
              JOIN opitemrece oi ON oi.an = o.an
              JOIN drugitems di ON di.icode = oi.icode
              WHERE o.an = periodized.an
                AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8154', '8155')
                AND (di.antibiotic = 'Y' OR di.drugcategory ILIKE '%antibio%')
                AND EXTRACT(EPOCH FROM (
                  (o.opdate + COALESCE(o.optime, TIME '00:00:00')) -
                  (oi.vstdate + COALESCE(oi.vsttime, TIME '00:00:00'))
                )) BETWEEN 0 AND 3600)) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE EXISTS (
          SELECT 1 FROM iptoprt o
          WHERE o.an = periodized.an
            AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8154', '8155')
        )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0302', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DO0302' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E1C\0E48\0E32\0E15\0E31\0E14\0E40\0E1B\0E25\0E35\0E48\0E22\0E19\0E02\0E49\0E2D\0E40\0E02\0E48\0E32\0020\0E44\0E14\0E49\0E23\0E31\0E1A\0020\0070\0072\006F\0070\0068\0079\006C\0061\0063\0074\0069\0063\0020\0061\006E\0074\0069\0062\0069\006F\0074\0069\0063' AS indicator_name_th,
            'Knee arthroplasty: Percent of patients who received antibiotic prophylaxis' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DO0302
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0303', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DO0303' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'T845'
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '365 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') = 'T845'
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') = 'T845'
                ))) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'T845'
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '365 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') = 'T845'
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') = 'T845'
                ))) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE EXISTS (
          SELECT 1 FROM iptoprt o
          WHERE o.an = periodized.an
            AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8154', '8155')
        )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0303', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DO0303' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E43\0E19\0E02\0E49\0E2D\0E40\0E02\0E48\0E32\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1C\0E48\0E32\0E15\0E31\0E14\0E40\0E1B\0E25\0E35\0E48\0E22\0E19\0E02\0E49\0E2D\0E40\0E02\0E48\0E32\0E20\0E32\0E22\0E43\0E19\0020\0031\0020\0E1B\0E35' AS indicator_name_th,
            'Knee artrhoplasty: Percent of surgical infection within 1 year' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DO0303
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0304', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DO0304' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('T845', 'T814')
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '90 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') IN ('T845', 'T814')
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') IN ('T845', 'T814')
                ))) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (
              SELECT 1
              FROM iptdiag sd
              WHERE sd.an = periodized.an
                AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('T845', 'T814')
              UNION
              SELECT 1
              FROM ipt r
              JOIN an_stat rs ON rs.an = r.an
              LEFT JOIN iptdiag rd ON rd.an = r.an
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '90 days'
                AND (
                  REPLACE(UPPER(TRIM(rs.pdx)), '.', '') IN ('T845', 'T814')
                  OR REPLACE(UPPER(TRIM(rd.icd10)), '.', '') IN ('T845', 'T814')
                ))) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE EXISTS (
          SELECT 1 FROM iptoprt o
          WHERE o.an = periodized.an
            AND REPLACE(UPPER(TRIM(o.icd9)), '.', '') IN ('8154', '8155')
        )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DO0304', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DO0304' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E15\0E34\0E14\0E40\0E0A\0E37\0E49\0E2D\0E43\0E19\0E02\0E49\0E2D\0E40\0E02\0E48\0E32\0E2B\0E25\0E31\0E07\0E01\0E32\0E23\0E1C\0E48\0E32\0E15\0E31\0E14\0E40\0E1B\0E25\0E35\0E48\0E22\0E19\0E02\0E49\0E2D\0E40\0E02\0E48\0E32\0E20\0E32\0E22\0E43\0E19\0020\0039\0030\0020\0E27\0E31\0E19' AS indicator_name_th,
            'Knee artrhoplasty: Percent of surgical infection within 90 days' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DO0304
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DP0101', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DP0101' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (
            WHERE EXISTS (
              SELECT 1 FROM lab_order lo
              JOIN lab_head lh ON lh.lab_order_number = lo.lab_order_number
              JOIN lab_items li ON li.lab_items_code = lo.lab_items_code
              WHERE lh.hn = periodized.hn
                AND li.lab_items_name ILIKE '%hba1c%'
                AND lh.order_date >= (SELECT fy_start FROM yspan) AND lh.order_date < (SELECT fy_end FROM yspan)
                AND CASE WHEN REGEXP_REPLACE(lo.lab_order_result, '[^0-9.]', '', 'g') ~ '^[0-9]*[.]?[0-9]+$' THEN CAST(REGEXP_REPLACE(lo.lab_order_result, '[^0-9.]', '', 'g') AS numeric) ELSE NULL END < 7.5
            )
          ) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE EXISTS (SELECT 1 FROM lab_order lo JOIN lab_head lh ON lh.lab_order_number = lo.lab_order_number JOIN lab_items li ON li.lab_items_code = lo.lab_items_code WHERE lh.hn = periodized.hn AND li.lab_items_name ILIKE '%hba1c%' AND lh.order_date >= (SELECT fy_start FROM yspan) AND lh.order_date < (SELECT fy_end FROM yspan) AND CASE WHEN REGEXP_REPLACE(lo.lab_order_result, '[^0-9.]', '', 'g') ~ '^[0-9]*[.]?[0-9]+$' THEN CAST(REGEXP_REPLACE(lo.lab_order_result, '[^0-9.]', '', 'g') AS numeric) ELSE NULL END < 7.5)) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE age_y < 18 AND (LEFT(pdx, 3) = 'E10' OR pdx IN ('E891', 'P702'))
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DP0101', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DP0101' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E40\0E1A\0E32\0E2B\0E27\0E32\0E19\0E0A\0E19\0E34\0E14\0E17\0E35\0E48\0020\0031\0020\0E43\0E19\0E40\0E14\0E47\0E01\0E41\0E25\0E30\0E27\0E31\0E22\0E23\0E38\0E48\0E19\0E2D\0E32\0E22\0E38\0E19\0E49\0E2D\0E22\0E01\0E27\0E48\0E32\0020\0031\0038\0020\0E1B\0E35\0E17\0E35\0E48\0E04\0E27\0E1A\0E04\0E38\0E21\0E23\0E30\0E14\0E31\0E1A\0020\0E19\0E49\0E33\0E15\0E32\0E25\0E44\0E14\0E49\0E14\0E35' AS indicator_name_th,
            'Diabetes in child and adolescent: Percent of good controlled of blood sugar (age < 18 years)' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DP0101
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0101', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DR0101' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE (LEFT(pdx, 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851') OR LEFT(pdx, 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')) AND died OR (has_pneumonia_sdx AND died_from_pneumonia)) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE (LEFT(pdx, 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851') OR LEFT(pdx, 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')) AND died OR (has_pneumonia_sdx AND died_from_pneumonia)) * 100.0) / NULLIF(COUNT(*), 0), 2) AS value
          FROM periodized
          WHERE LEFT(pdx, 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851') OR LEFT(pdx, 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18') OR has_pneumonia_sdx
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0101', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DR0101' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E40\0E2A\0E35\0E22\0E0A\0E35\0E27\0E34\0E15\0E2B\0E25\0E31\0E07\0E08\0E32\0E01\0E40\0E02\0E49\0E32\0E23\0E31\0E1A\0E01\0E32\0E23\0E23\0E31\0E01\0E29\0E32\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21' AS indicator_name_th,
            'Pneumonia: Percent of mortality after hospital admission' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DR0101
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0102', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DR0102' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
        
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) AS numerator,
            COUNT(*) FILTER (WHERE NOT died) AS denominator,
            ROUND((
            COUNT(*) FILTER (WHERE NOT died AND EXISTS (
              SELECT 1
              FROM ipt r
              WHERE r.hn = periodized.hn
                AND r.an <> periodized.an
                AND r.regdate > periodized.dchdate
                AND r.regdate <= periodized.dchdate + INTERVAL '28 days'
            )) * 100.0) / NULLIF(COUNT(*) FILTER (WHERE NOT died), 0), 2) AS value
          FROM periodized
          WHERE LEFT(pdx, 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851') OR LEFT(pdx, 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18') OR has_pneumonia_sdx
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0102', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DR0102' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E01\0E32\0E23\0E23\0E31\0E1A\0E01\0E25\0E31\0E1A\0E40\0E02\0E49\0E32\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25\0E02\0E2D\0E07\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E20\0E32\0E22\0E43\0E19\0020\0032\0038\0020\0E27\0E31\0E19\0020\0E42\0E14\0E22\0E44\0E21\0E48\0E44\0E14\0E49\0E27\0E32\0E07\0E41\0E1C\0E19' AS indicator_name_th,
            'Pneumonia: Percent of unplanned re-admission within 28 days after last discharge' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'lower-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'lower-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DR0102
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0103', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
          )) >= 14400
      ),
      periodized AS (
        SELECT
          *,
          DATE_TRUNC('month', dchdate)::date AS period_start,
          EXTRACT(MONTH FROM dchdate)::integer AS calendar_month
        FROM ipd
      ),
          opd_periodized AS (
        SELECT
          v.vn,
          v.hn,
          v.an,
          EXTRACT(YEAR FROM AGE(v.vstdate, pd.birthday))::integer AS age_y,
          pd.sex,
          (SELECT REPLACE(UPPER(TRIM(sd.icd10)), '.', '')
             FROM ovstdiag sd
            WHERE sd.vn = v.vn AND sd.diagtype = '1'
            ORDER BY sd.ovst_diag_id
            LIMIT 1) AS pdx,
          v.vstdate AS event_date,
          er.enter_er_time,
          er.triage_datetime,
          er.doctor_tx_time,
          er.finish_time,
          er.antibiotics_datetime,
          er.stroke_needle_datetime,
          er.stemi_balloon_datetime,
          er.er_emergency_level_id,
          er.unplanned_return,
          er.news2_score,
          DATE_TRUNC('month', v.vstdate)::date AS period_start,
          EXTRACT(MONTH FROM v.vstdate)::integer AS calendar_month
        FROM ovst v
        LEFT JOIN patient pd ON pd.hn = v.hn
        LEFT JOIN er_regist er ON er.vn = v.vn
        WHERE v.vstdate >= (SELECT fy_start FROM yspan)
          AND v.vstdate < (SELECT fy_end FROM yspan)
      ),
      chronic_periodized AS (
        SELECT
          cm.clinicmember_id,
          cm.clinic,
          cm.hn,
          cm.regdate,
          cm.lastvisit,
          cm.dchdate,
          cm.current_status,
          cm.clinic_member_status_id,
          cm.age_y,
          cm.sex,
          cm.chronic_type,
          cm.begin_year,
          cm.last_hba1c_value,
          cm.last_hba1c_date,
          cm.last_bp_bps_value,
          cm.last_bp_bpd_value,
          cm.last_bp_date,
          DATE_TRUNC('month', cm.regdate)::date AS period_start,
          EXTRACT(MONTH FROM cm.regdate)::integer AS calendar_month
        FROM clinicmember cm
        WHERE cm.regdate >= (SELECT fy_start FROM yspan)
          AND cm.regdate < (SELECT fy_end FROM yspan)
      ),
      delivery_periodized AS (
        SELECT
          l.laborid,
          l.an,
          l.hage AS mother_age_y,
          l.labor_type,
          l.mother_method,
          l.infant_sex,
          l.infant_weight,
          l.infant_apgarscore1,
          l.infant_apgarscore5,
          l.infant_apgarscore10,
          l.placenta_bloodloss,
          l.labour_startdate,
          l.labour_finishdate,
          DATE_TRUNC('month', COALESCE(l.labour_startdate, i.regdate))::date AS period_start,
          EXTRACT(MONTH FROM COALESCE(l.labour_startdate, i.regdate))::integer AS calendar_month
        FROM labor l
        LEFT JOIN ipt i ON i.an = l.an
        WHERE COALESCE(l.labour_startdate, i.regdate) >= (SELECT fy_start FROM yspan)
          AND COALESCE(l.labour_startdate, i.regdate) < (SELECT fy_end FROM yspan)
      ),
      newborn_periodized AS (
        SELECT
          nb.an,
          nb.mother_an,
          nb.born_date,
          nb.birth_weight,
          nb.apgar1,
          nb.apgar2,
          nb.dead,
          nb.has_asphyxia,
          nb.birthcondition1,
          nb.birthcondition2,
          nb.anc_complete,
          DATE_TRUNC('month', nb.born_date)::date AS period_start,
          EXTRACT(MONTH FROM nb.born_date)::integer AS calendar_month
        FROM ipt_newborn nb
        WHERE nb.born_date >= (SELECT fy_start FROM yspan)
          AND nb.born_date < (SELECT fy_end FROM yspan)
      ),
      emp_periodized AS (
        SELECT
          e.emp_id,
          e.emp_sex_id,
          e.emp_birthdate,
          e.emp_status_id,
          e.emp_type_id,
          e.emp_dep_id,
          e.emp_position_main_id,
          e.emp_work_begindate,
          e.emp_resign_enddate,
          e.emp_resign_type_id,
          DATE_TRUNC('month', e.emp_work_begindate)::date AS period_start,
          EXTRACT(MONTH FROM e.emp_work_begindate)::integer AS calendar_month
        FROM emp e
        WHERE e.emp_work_begindate >= (SELECT fy_start FROM yspan)
          AND e.emp_work_begindate < (SELECT fy_end FROM yspan)
      ),
          facts AS (
      
          SELECT
            'DR0103' AS indicator_code,
            DATE_TRUNC('month', period_start)::date AS period_start,
            CASE WHEN calendar_month >= 10 THEN calendar_month - 9 ELSE calendar_month + 3 END AS fiscal_month,
            CASE WHEN calendar_month >= 10 THEN EXTRACT(YEAR FROM period_start)::integer + 1 ELSE EXTRACT(YEAR FROM period_start)::integer END AS fiscal_year,
            COUNT(*) FILTER (WHERE (
              EXISTS (
                SELECT 1
                FROM iptdiag sd
                WHERE sd.an = periodized.an
                  AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen scr
                JOIN ovst v ON v.vn = scr.vn
                WHERE v.an = periodized.an
                  AND (
                    scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                    OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                    OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                    OR scr.advice7_note ILIKE '%smoke%'
                    OR scr.advice7_note ILIKE '%สูบ%'
                  )
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen_advice adv
                JOIN opdscreen_advice_item itm ON itm.opdscreen_advice_item_id = adv.opdscreen_advice_item_id
                JOIN ovst v ON v.vn = adv.vn
                WHERE v.an = periodized.an
                  AND (
                    itm.opdscreen_advice_item_name ILIKE '%smoke%'
                    OR itm.opdscreen_advice_item_name ILIKE '%บุหรี่%'
                  )
              )
            )) AS numerator,
            COUNT(*) AS denominator,
            ROUND((COUNT(*) FILTER (WHERE (
              EXISTS (
                SELECT 1
                FROM iptdiag sd
                WHERE sd.an = periodized.an
                  AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z716'
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen scr
                JOIN ovst v ON v.vn = scr.vn
                WHERE v.an = periodized.an
                  AND (
                    scr.advice1 = 'Y' OR scr.advice2 = 'Y' OR scr.advice3 = 'Y'
                    OR scr.advice4 = 'Y' OR scr.advice5 = 'Y' OR scr.advice6 = 'Y'
                    OR scr.advice7 = 'Y' OR scr.advice8 = 'Y'
                    OR scr.advice7_note ILIKE '%smoke%'
                    OR scr.advice7_note ILIKE '%สูบ%'
                  )
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen_advice adv
                JOIN opdscreen_advice_item itm ON itm.opdscreen_advice_item_id = adv.opdscreen_advice_item_id
                JOIN ovst v ON v.vn = adv.vn
                WHERE v.an = periodized.an
                  AND (
                    itm.opdscreen_advice_item_name ILIKE '%smoke%'
                    OR itm.opdscreen_advice_item_name ILIKE '%บุหรี่%'
                  )
              )
            ))) * 100 / NULLIF((COUNT(*)), 0), 2) AS value
          FROM periodized
          WHERE (LEFT(pdx, 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851') OR LEFT(pdx, 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')) AND (
              EXISTS (
                SELECT 1
                FROM iptdiag sd
                WHERE sd.an = periodized.an
                  AND (
                    LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) = 'F17'
                    OR REPLACE(UPPER(TRIM(sd.icd10)), '.', '') = 'Z720'
                  )
              )
              OR EXISTS (
                SELECT 1
                FROM opdscreen scr
                JOIN ovst v ON v.vn = scr.vn
                WHERE v.an = periodized.an
                  AND scr.smoking_type_id IN (2, 3)
              )
            )
          GROUP BY 2, 3, 4
          ),
          agg AS (
            SELECT
              facts.fiscal_year + 543 AS fiscal_year_be,
              SUM(COALESCE(facts.numerator, 0)) AS num_sum,
              SUM(COALESCE(facts.denominator, 0)) AS den_sum,
              SUM(facts.value) AS val_sum
            FROM facts
            GROUP BY 1
          ),
          targets AS (
            SELECT y.fiscal_year,
                   MAX(COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                                m.kpi_moph_number_c, m.kpi_moph_number_b,
                                m.kpi_moph_number_a)) AS target_value
            FROM years y
            LEFT JOIN kpi_moph_guideline g
              ON UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                 ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0103', '\.', '\.?', 'g') || '($|[^0-9])')
            LEFT JOIN kpi_moph m
              ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
             AND (CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                       WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543 END) = y.fiscal_year
            GROUP BY y.fiscal_year
          ),
          per_year AS (
            SELECT y.fiscal_year,
                   COALESCE(a.num_sum, 0) AS numerator,
                   COALESCE(a.den_sum, 0) AS denominator,
                   CASE WHEN a.num_sum IS NOT NULL AND a.den_sum > 0
                        THEN ROUND(a.num_sum * 100.0 / a.den_sum, 2)
                        ELSE a.val_sum END AS value
            FROM years y
            LEFT JOIN agg a ON a.fiscal_year_be = y.fiscal_year
          )
          SELECT
            'DR0103' AS indicator_code,
            U&'\0E23\0E49\0E2D\0E22\0E25\0E30\0E1C\0E39\0E49\0E1B\0E48\0E27\0E22\0E42\0E23\0E04\0E1B\0E2D\0E14\0E1A\0E27\0E21\0E44\0E14\0E49\0E23\0E31\0E1A\0E04\0E33\0E41\0E19\0E30\0E19\0E33\0E43\0E2B\0E49\0E2D\0E14\0E2B\0E23\0E37\0E2D\0E40\0E25\0E34\0E01\0E1A\0E38\0E2B\0E23\0E35\0E48\0020\0E23\0E30\0E2B\0E27\0E48\0E32\0E07\0E2D\0E22\0E39\0E48\0E43\0E19\0E42\0E23\0E07\0E1E\0E22\0E32\0E1A\0E32\0E25' AS indicator_name_th,
            'Pneumonia: Percent of smoking cessation advice given' AS indicator_name_en,
            make_date(p.fiscal_year - 544, 10, 1) AS period_start,
            p.fiscal_year AS fiscal_year,
            p.numerator,
            p.denominator,
            p.value,
            t.target_value AS target,
            CASE WHEN p.value IS NULL OR t.target_value IS NULL OR t.target_value = 0
                 THEN NULL
                 ELSE ROUND(p.value * 100.0 / t.target_value, 2) END AS vs_target_pct,
            CASE WHEN p.value IS NULL THEN 'no-data'
                 WHEN t.target_value IS NULL OR 'higher-is-better' = 'neutral' THEN 'unbenchmarked'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'higher-is-better' AND p.value >= t.target_value - GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value THEN 'on-track'
                 WHEN 'higher-is-better' = 'lower-is-better' AND p.value <= t.target_value + GREATEST(ABS(t.target_value) * 0.08, 0.02) THEN 'watch'
                 ELSE 'action' END AS status
          FROM per_year p
          LEFT JOIN targets t ON t.fiscal_year = p.fiscal_year
          ORDER BY p.fiscal_year
  ) AS y_DR0103
  UNION ALL
  SELECT * FROM (
    WITH
          thip_params AS (
            SELECT
              v.fiscal_year,
              -- ปีงบประมาณไทยเริ่ม 1 ต.ค.:  พ.ศ. Y -> 1 ต.ค. ค.ศ. (Y-544)
              make_date(v.fiscal_year - 544, 10, 1) AS fy_start,
              -- 1 ต.ค. ของปีถัดไป = ขอบเขตบนแบบไม่รวม (exclusive) คือวันสุดท้าย 30 ก.ย. (Y-543)
              make_date(v.fiscal_year - 543, 10, 1) AS fy_end
            FROM (VALUES (2569)) AS v(fiscal_year)
          ),
          years_raw AS (
            SELECT DISTINCT CASE WHEN m.kpi_moph_year >= 2400 THEN m.kpi_moph_year
                                 WHEN m.kpi_moph_year BETWEEN 2000 AND 2399 THEN m.kpi_moph_year + 543
                            END AS fiscal_year
            FROM kpi_moph_guideline g
            JOIN kpi_moph m ON m.kpi_moph_guideline_id = g.kpi_moph_guideline_id
            WHERE UPPER(COALESCE(g.kpi_moph_guideline_name, '')) ~
                  ('(^|[^0-9A-Z])' || REGEXP_REPLACE('DR0201', '\.', '\.?', 'g') || '($|[^0-9])')
              AND COALESCE(m.kpi_moph_number_result, m.kpi_moph_number_mean,
                           m.kpi_moph_number_c, m.kpi_moph_number_b,
                           m.kpi_moph_number_a) IS NOT NULL
            UNION
            SELECT (SELECT fiscal_year FROM thip_params)
          ),
          years AS (
            SELECT fiscal_year FROM years_raw WHERE fiscal_year IS NOT NULL
          ),
          yspan AS (
            SELECT MIN(make_date(fiscal_year - 544, 10, 1)) AS fy_start,
                   MAX(make_date(fiscal_year - 543, 10, 1)) AS fy_end
            FROM years
          ),
          ipd AS (
        SELECT
          i.an,
          i.hn,
          i.regdate,
          i.regtime,
          i.dchdate,
          COALESCE(i.bw, 0) AS bw,
          s.age_y,
          s.los,
          REPLACE(UPPER(TRIM(s.pdx)), '.', '') AS pdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
          ) AS died,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
          ) AS has_acs_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213', 'I214', 'I219')
              )
          ) AS died_from_acs,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
          ) AS has_stemi_sdx,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('I214', 'I219')
          ) AS has_nste_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND d.death_date IS NOT NULL
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) >=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
              AND (d.death_date + COALESCE(d.death_time, TIME '23:59:59')) <=
                (i.regdate + COALESCE(i.regtime, TIME '00:00:00')) + INTERVAL '48 hours'
          ) AS died_within_48h,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I210', 'I211', 'I212', 'I213')
              )
          ) AS died_from_stemi,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_cause)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_1)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_2)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_3)), '.', '') IN ('I214', 'I219')
                OR REPLACE(UPPER(TRIM(d.death_diag_4)), '.', '') IN ('I214', 'I219')
              )
          ) AS died_from_nste,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') <> REPLACE(UPPER(TRIM(s.pdx)), '.', '')
              AND (
                LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(sd.icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS has_pneumonia_sdx,
          EXISTS (
            SELECT 1
            FROM death d
            WHERE d.an = i.an
              AND (
                LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_icd10)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_cause)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_1)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_2)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_3)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 3) IN ('J12', 'J13', 'J14', 'J15', 'J16', 'J18')
                OR LEFT(REPLACE(UPPER(TRIM(d.death_diag_4)), '.', ''), 4) IN ('J100', 'J110', 'J170', 'J171', 'J172', 'J173', 'J178', 'J850', 'J851')
              )
          ) AS died_from_pneumonia,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A419', 'R572', 'R651')
          ) AS has_ce0101_sepsis,
          EXISTS (
            SELECT 1
            FROM iptdiag sd
            WHERE sd.an = i.an
              AND REPLACE(UPPER(TRIM(sd.icd10)), '.', '') IN ('A400', 'A409', 'A410', 'A419', 'R572', 'R651')
          ) AS has_ci0101_sepsis
        FROM ipt i
        JOIN an_stat s ON s.an = i.an
        WHERE i.dchdate >= (SELECT fy_start FROM yspan)
          AND i.dchdate < (SELECT fy_end FROM yspan)
          AND i.regdate IS NOT NULL
          AND EXTRACT(EPOCH FROM (
            (i.dchdate + COALESCE(i.dchtime, TIME '23:59:59')) -
            (i.regdate + COALESCE(i.regtime, TIME '00:00:00'))
